def countNicePairs(nums):
    MOD = 10**9 + 7

    def reverse(x):
        res = 0
        while x > 0:
            res = res * 10 + x % 10
            x //= 10
        return res

    count = {}  # key: nums[i] - rev(nums[i]), value: frequency
    result = 0

    for num in nums:
        key = num - reverse(num)
        if key in count:
            result = (result + count[key]) % MOD  # add new pairs formed
            count[key] += 1
        else:
            count[key] = 1

    return result
